import{_ as o,o as t,c as a,a3 as r}from"./chunks/framework.DACwFHq9.js";const u=JSON.parse('{"title":"Data & Sync Security","description":"Security, storage layout, local encryption, and data protection guidelines for Notely workspaces.","frontmatter":{"title":"Data & Sync Security","description":"Security, storage layout, local encryption, and data protection guidelines for Notely workspaces.","keywords":"data, security, sync, git, local storage, notes-app","category":"Sync"},"headers":[],"relativePath":"data-sync-security.md","filePath":"data-sync-security.md","lastUpdated":1791395946000}'),i={name:"data-sync-security.md"};function s(n,e,l,c,d,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="data-sync" tabindex="-1">Data &amp; Sync <a class="header-anchor" href="#data-sync" aria-label="Permalink to &quot;Data &amp; Sync&quot;">​</a></h1><p>This guide explains how Notely stores your data and how to keep work safe when collaborating.</p><h2 id="_1-where-notely-stores-app-data" tabindex="-1">1. Where Notely Stores App Data <a class="header-anchor" href="#_1-where-notely-stores-app-data" aria-label="Permalink to &quot;1. Where Notely Stores App Data&quot;">​</a></h2><p>Notely keeps your notes in your selected workspace folder.</p><p>It also creates a <code>.notes-app</code> folder for app-managed data such as:</p><ul><li>Note version history</li><li>Workspace settings</li><li>Image annotations</li></ul><p>You usually do not need to open or edit those files yourself.</p><h2 id="_2-keep-your-notes-safe" tabindex="-1">2. Keep Your Notes Safe <a class="header-anchor" href="#_2-keep-your-notes-safe" aria-label="Permalink to &quot;2. Keep Your Notes Safe&quot;">​</a></h2><p>Notely includes built-in safety features:</p><ul><li>Version history for restoring previous note content</li><li>Managed handling for removed notes/folders</li><li>Conflict tools when synced changes overlap</li></ul><p>Best practice: make sure your workspace folder is backed up regularly.</p><h2 id="_3-sync-with-remote-repositories-git" tabindex="-1">3. Sync with Remote Repositories (Git) <a class="header-anchor" href="#_3-sync-with-remote-repositories-git" aria-label="Permalink to &quot;3. Sync with Remote Repositories (Git)&quot;">​</a></h2><ol><li>Open <strong>Tools -&gt; Version Control</strong> (<code>Ctrl/Cmd + Shift + G</code>).</li><li>Add your remote repository URL (GitHub, GitLab, self-hosted).</li><li>Use <strong>Sync (Pull then Push)</strong> to synchronize note changes across devices.</li><li>If merge conflicts occur, use the built-in visual diff tool to resolve them cleanly.</li></ol><h2 id="_4-ai-mcp-integration-for-daily-use" tabindex="-1">4. AI &amp; MCP Integration for Daily Use <a class="header-anchor" href="#_4-ai-mcp-integration-for-daily-use" aria-label="Permalink to &quot;4. AI &amp; MCP Integration for Daily Use&quot;">​</a></h2><ol><li>Open <strong>AI -&gt; AI Settings</strong> (<code>Ctrl/Cmd + Shift + ,</code>).</li><li>Configure your preferred Speech-to-Text engine (Local ONNX Whisper or Cloud Groq/OpenAI) and API keys.</li><li>Connect external AI assistants (Google Antigravity, Claude Desktop, Cursor) directly to Notely via the built-in MCP server on port <code>3700</code>.</li><li>Use hybrid semantic search and knowledge graph discovery locally and securely.</li></ol><h2 id="_5-when-to-use-workspace-graph" tabindex="-1">5. When to Use Workspace Graph <a class="header-anchor" href="#_5-when-to-use-workspace-graph" aria-label="Permalink to &quot;5. When to Use Workspace Graph&quot;">​</a></h2><p>Open <strong>Workspace -&gt; Workspace Graph</strong> when you want to:</p><ul><li>Find related notes quickly</li><li>Spot disconnected notes</li><li>Understand media-to-note relationships</li></ul><h2 id="_6-before-sharing-or-releasing-notes" tabindex="-1">6. Before Sharing or Releasing Notes <a class="header-anchor" href="#_6-before-sharing-or-releasing-notes" aria-label="Permalink to &quot;6. Before Sharing or Releasing Notes&quot;">​</a></h2><p>Do this quick check:</p><ol><li>Validate markdown issues.</li><li>Review typo warnings.</li><li>Open important diagrams in preview.</li><li>Confirm linked files still open correctly.</li></ol>',21)])])}const y=o(i,[["render",s]]);export{u as __pageData,y as default};
